#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Profil: avatar kiri; di kanannya nickname > ID > badge role > badge lain. Background VIP/SVIP.
# Jalankan di root repo:  bash pasang-profil.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/ProfileFragment.kt" ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-profil-$(date +%H%M%S)"
FIXED=0
fix() {
  f="$1"; m="$2"
  if [ -f "$f" ] && grep -q -- "$m" "$f"; then
    echo "  ok         $f"
  else
    [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
    cp "$T/new/$f" "$f"
    echo "  DIPERBAIKI $f"
    FIXED=$((FIXED+1))
  fi
}
fix $D/FlowRow.kt                                "centered: Boolean = false"
fix $D/ProfileTheme.kt                           "object ProfileTheme"
fix $D/ProfileFragment.kt                        "ProfileTheme.background"
fix $D/SvgaPlayer.kt                             "ALIGN_LEFT"
fix app/src/main/res/layout/fragment_profile.xml 'toEndOf="@id/img_avatar"'
rm -rf "$T"
[ "$FIXED" -eq 0 ] && echo "✅ Sudah terpasang, tidak ada yang diubah." || echo "✅ $FIXED file dipasang (backup lama: $BK)"
if [ -d .git ] && [ "$FIXED" -gt 0 ]; then
  BR=$(git rev-parse --abbrev-ref HEAD)
  git add -A
  git commit -m "profil: avatar kiri, nick > ID > role > badge, background VIP/SVIP" || true
  git pull --rebase --autostash origin "$BR" || { echo "⚠️ Konflik saat pull, selesaikan lalu: git rebase --continue && git push origin $BR"; exit 1; }
  git push origin "$BR"
  echo "✅ Terkirim ke origin/$BR"
fi
